import{_ as a,c as e,o as p,a4 as o}from"./chunks/framework.4aTu-Nia.js";const b=JSON.parse('{"title":"21世纪的管理挑战","description":"","frontmatter":{},"headers":[],"relativePath":"books/21世纪的管理挑战.md","filePath":"books/21世纪的管理挑战.md"}'),t={name:"books/21世纪的管理挑战.md"},l=o('<h1 id="_21世纪的管理挑战" tabindex="-1">21世纪的管理挑战 <a class="header-anchor" href="#_21世纪的管理挑战" aria-label="Permalink to &quot;21世纪的管理挑战&quot;">​</a></h1><p>彼得·德鲁克的《21世纪的管理挑战》是一本经典的管理学著作，强调了在信息技术快速发展和全球化的背景下</p><blockquote><p>管理的本质在于决策。德鲁克认为，管理者的核心职责是做出决策，并将这些决策转化为行动。因此，管理者需要具备清晰的思维和有效的决策能力。</p></blockquote><blockquote><p>管理者应该聚焦于机会而非问题。德鲁克提出了“创造性无聊”这个概念，意味着管理者需要专注于未来的机会而非过去的问题。管理者应该从市场、技术、人才等角度来寻找新的机会。</p></blockquote><h2 id="自主、创新、质量" tabindex="-1">自主、创新、质量 <a class="header-anchor" href="#自主、创新、质量" aria-label="Permalink to &quot;自主、创新、质量&quot;">​</a></h2><p>知识工作者 6 要素：</p><ol><li>要提高效果，需要问 任务是什么</li><li>必须自我管理，有自主权</li><li>任务、责任包括不断创新</li><li>不断接受教育，同样不断指导别人学习</li><li>不能或至少不能只用数量衡量，质量至少与数量同样重要</li></ol><p>在可能的情况下，能取得最高的质量最好，然后才问，完成了多少工作量</p><p>体力劳动者，不会问做什么，问怎么做好</p><p>知识工作，关键性问题，任务是什么</p><p>放弃哪些？打杂</p><p>主观判断，任务难度</p><p>知识工作者 寿命延长 很可能可以活动 80 岁 可能需要继续工作 即使兼职工作 至少也要工作到 75 岁 平均工作年限可能长达 50 年</p><h2 id="发挥长处" tabindex="-1">发挥长处 <a class="header-anchor" href="#发挥长处" aria-label="Permalink to &quot;发挥长处&quot;">​</a></h2><p>了解自己的长处，只能发挥长处创造绩效</p><p>如果我们认识到我们不能胜任决策者的角色，在有机会成为决策者时，我们就应该学会说不。</p><p>如果以 我应做出什么样的贡献 为出发点，我们就拥有了自由。这种自由是建立在责任的基础上的。</p><p>在哪些方面，我可以创造出不同凡响的成绩？如何创造？</p><h2 id="反馈分析法" tabindex="-1">反馈分析法 <a class="header-anchor" href="#反馈分析法" aria-label="Permalink to &quot;反馈分析法&quot;">​</a></h2><p>反馈分析法：无论做出什么样的决策，采取什么关键措施，我们都写下我们希望看到的结果。9-12个月后，我们就可以将实际的结果与预期的结果进行对比</p><ol><li>克服傲慢倾向，努力学习能充分发挥优势的技能和知识</li><li>什么是不要做的事</li><li>在改进弱点上，我们要尽可能少浪费精力</li></ol><p>了解到哪些工作是尤其不能胜任的</p><p>认识到不具有优势和不能涉足的领域</p><h2 id="善于阅读-还是善于倾听" tabindex="-1">善于阅读，还是善于倾听 <a class="header-anchor" href="#善于阅读-还是善于倾听" aria-label="Permalink to &quot;善于阅读，还是善于倾听&quot;">​</a></h2><p>会议一开完，记录会上讨论的关键性问题、会议上提出的问题、达成的决策以及发现但未解决的问题</p><p>如果在会后我不立即坐下来，思考会以上实际讨论的内容，然后以局面形式记下来，我就会在 24 小时内忘得一干二净。</p><p>需要有人听他说话，与自己辩论 站在三种不同的立场上分析每一个问题：造成、反对和有利于行动计划达成目标的形势</p><p>让学生听我讲课是我教书的原因，因为那样，我才能写作的灵感</p><p>对镜测试法，早上刮脸时，我想看到什么样的人</p><h2 id="以礼待人-组织润滑剂" tabindex="-1">以礼待人 - 组织润滑剂 <a class="header-anchor" href="#以礼待人-组织润滑剂" aria-label="Permalink to &quot;以礼待人 - 组织润滑剂&quot;">​</a></h2><p>聪明的人，特别是精明强干的年轻人常常没有认识到以礼待人是组织的润滑剂</p><p>大多数人都要与做不同工作的人共事</p><p>对方是善于阅读的人，还是善于倾听的人？</p><p>组织的基础不再是权力，信任日益成为组织存在的基础。</p><p>要自我管理，需要为自己的下半生做好准备</p><p>平均寿命、工作时间，越来越长</p><p>书：中场休息 half time 下半场赢家 game plan</p><p>个人极限运动，需要认真的准备和极度的冷静 目的不是寻求刺激 而是在过程中感受到自己的能力有多强大 需要冷静的头脑、经验和技巧，还有特别强大的体能 一切自我控制 当开始的时候 一定是我准备好的时候 不像过山车把命运交给别人</p><h2 id="读后反思" tabindex="-1">读后反思 <a class="header-anchor" href="#读后反思" aria-label="Permalink to &quot;读后反思&quot;">​</a></h2><p>基础与算法并举： 等把算法刷好，其它的都耽误了。都有一长，别算法不好，基础也不行。所以要同时刷，找牛客等网站。要让自己有亮点、有进步提升。</p>',40),i=[l];function r(h,n,s,c,_,d){return p(),e("div",null,i)}const m=a(t,[["render",r]]);export{b as __pageData,m as default};
